// Generated by Suite Builder from a crawl of the site. The test library: every family and test on one page, run from a click (node menu/library.mjs).
// EDIT RULES: do not edit this file; regenerating replaces all of it. The menu is menu/menu.mjs; your own commands go in a file of your own.
// The test library (TODO 33): every family and test of this suite on one page, and a click runs one.
// Started by the menu ("Open the test library") or `node menu/library.mjs`; serves a page on this computer
// only (127.0.0.1), opens it in the browser, and runs nothing but this suite's own tests (G-167), one run at a
// time. Every request carries a key only the page knows, so no other page in the browser can start a run.
import { spawn, spawnSync } from 'node:child_process';
import { randomBytes } from 'node:crypto';
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs';
import { createServer } from 'node:http';
import { dirname, join, relative, sep } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
const SITE = "playwright-playground.com";
const FRAMEWORK = "Playwright";
/** java (Maven, JUnit tags) or cypress (npm, tags in the specs). */
const KIND = "java";
/** The run's report page. */
const REPORT = "target/report.html";
const WIN = process.platform === 'win32';
const KEY = randomBytes(16).toString('hex');

// ---- What the suite holds (this framework's part: its families, tests, results and commands) -----

const read = (file) => readFileSync(file, 'utf8');
const posix = (path) => path.split(sep).join('/');
function walk(dir, keep) {
  if (!existsSync(dir)) return [];
  return readdirSync(dir).flatMap((name) => {
    const path = join(dir, name);
    return statSync(path).isDirectory() ? walk(path, keep) : keep(name) ? [path] : [];
  });
}

const MAVEN = 'mvn';

/** The families: name and what it checks, from Family.java's annotations. */
function families() {
  const file = walk(join(ROOT, 'src', 'test', 'java'), (n) => n === 'Family.java')[0];
  if (!file) return [];
  const text = read(file);
  return [...text.matchAll(/\/\*\*\s*(.*?)(?::\s*\w+ test[^*]*)?\*\/\s*@Tag\("([\w-]+)"\)[\s\S]*?public @interface (\w+)/g)].map((m) => ({ name: m[2], what: m[1].trim(), annotation: m[3] }));
}

/** Java: each concrete test class's tests (its own and what it inherits), with the families of each. */
function tests(fams) {
  const byAnnotation = new Map(fams.map((f) => [f.annotation, f.name]));
  const tagsIn = (lines) => [...lines.join('\n').matchAll(/@Tag\("([\w-]+)"\)|@Family\.(\w+)/g)].map((m) => m[1] ?? byAnnotation.get(m[2])).filter(Boolean);
  const classes = new Map();
  for (const file of walk(join(ROOT, 'src', 'test', 'java'), (n) => n.endsWith('.java'))) {
    const lines = read(file).split(/\r?\n/);
    const decl = lines.findIndex((l) => /^\s*(public\s+|abstract\s+|final\s+)*class\s+\w+/.test(l));
    if (decl < 0) continue;
    const head = /class\s+(\w+)(?:\s+extends\s+(\w+))?/.exec(lines[decl]);
    let start = decl;
    while (start > 0 && /^\s*@/.test(lines[start - 1])) start--;
    const tests = [];
    let pending = [];
    for (const line of lines.slice(decl + 1)) {
      if (/^\s*@/.test(line)) pending.push(line);
      else if (/^\s*(public\s+|protected\s+)?void\s+(\w+)\s*\(/.test(line)) {
        const name = /void\s+(\w+)/.exec(line)[1];
        if (pending.some((l) => /@(Test|ParameterizedTest)\b/.test(l))) {
          const shown = pending.map((l) => /@DisplayName\((".*")\)/.exec(l)?.[1]).find(Boolean);
          tests.push({ method: name, title: shown ? JSON.parse(shown) : name, tags: tagsIn(pending) });
        }
        pending = [];
      } else if (line.trim() && !line.trim().startsWith('//') && !line.trim().startsWith('*') && !line.trim().startsWith('/*')) pending = [];
    }
    classes.set(head[1], { name: head[1], parent: head[2], abstract: /\babstract\b/.test(lines[decl]), tags: tagsIn(lines.slice(start, decl + 1)), tests, file: posix(relative(ROOT, file)) });
  }
  const out = [];
  for (const c of classes.values()) {
    if (c.abstract || !c.tests.length && !classes.get(c.parent)?.tests.length) continue;
    const chain = [];
    for (let k = c; k; k = classes.get(k.parent)) chain.push(k);
    const classTags = chain.flatMap((k) => k.tags);
    const seen = new Set();
    for (const k of chain) {
      for (const t of k.tests) {
        if (seen.has(t.method)) continue;
        seen.add(t.method);
        out.push({ id: `${c.name}#${t.method}`, group: c.name, title: t.title, families: [...new Set([...classTags, ...t.tags])], file: c.file });
      }
    }
  }
  return out;
}

/** The last result of each test, by id, from the last run's reports. */
function lastResults(tests) {
  const results = {};
  for (const file of walk(join(ROOT, 'target', 'surefire-reports'), (n) => /^TEST-.*\.xml$/.test(n))) {
    for (const m of read(file).matchAll(/<testcase\b([^>]*?)(\/>|>([\s\S]*?)<\/testcase>)/g)) {
      const name = /name="([^"]*)"/.exec(m[1])?.[1] ?? '';
      const cls = (/classname="([^"]*)"/.exec(m[1])?.[1] ?? '').split('.').pop();
      const body = m[3] ?? '';
      const state = /<(failure|error)\b/.test(body) ? 'failed' : /<skipped\b/.test(body) ? 'skipped' : 'passed';
      const t = tests.find((x) => x.group === cls && (name === x.id.split('#')[1] || name.startsWith(`${x.id.split('#')[1]}(`) || name === x.title || name.startsWith(x.title)));
      if (t && results[t.id] !== 'failed') results[t.id] = state;
    }
  }
  return results;
}

/** The suite's own command for what was clicked. */
function commandFor(what) {
  if (what.family) return [MAVEN, 'test', `-Dgroups=${what.family}`];
  if (what.tests) return [MAVEN, 'test', `-Dtest=${what.tests.join(',')}`];
  return null;
}


function library() {
  const fams = families();
  const all = tests(fams);
  return { site: SITE, framework: FRAMEWORK, kind: KIND, families: fams, tests: all, results: lastResults(all), running: run.label };
}

// ---- Running ---------------------------------------------------------------------------------

const run = { child: null, label: null, lines: [], listeners: new Set(), code: null };

function say(line) {
  run.lines.push(line);
  if (run.lines.length > 5000) run.lines.shift();
  for (const listener of run.listeners) listener(line);
}

function start(what, label) {
  if (run.child) return `A run is going: ${run.label}. Stop it first.`;
  // Only a family or a test the library lists runs: nothing typed reaches the command.
  const known = library();
  const listed = what.family ? known.families.some((f) => f.name === what.family) : Array.isArray(what.tests) && what.tests.length > 0 && what.tests.every((t) => known.tests.some((k) => k.id === t || k.group === t));
  const cmd = listed ? commandFor(what) : null;
  if (!cmd || !/^[\w#,.:/=-]+$/.test(cmd.slice(1).join(''))) return 'Nothing to run.';
  if (KIND === 'cypress' && !existsSync(join(ROOT, 'node_modules'))) return 'First, once: npm install, in this folder (it downloads what the tests need).';
  run.lines = [];
  run.code = null;
  run.label = label;
  say(`$ ${cmd[0] === process.execPath ? 'node' : cmd[0]} ${cmd.slice(1).join(' ')}`);
  const child = spawn(cmd[0], cmd.slice(1), { cwd: ROOT, shell: WIN && cmd[0] !== process.execPath, detached: !WIN, env: { ...process.env, FORCE_COLOR: '0', NO_COLOR: '1' } });
  run.child = child;
  const lines = (stream) => {
    let rest = '';
    stream.on('data', (d) => {
      const text = rest + d.toString();
      const parts = text.split(/\r?\n/);
      rest = parts.pop();
      for (const p of parts) say(p);
    });
    stream.on('end', () => rest && say(rest));
  };
  lines(child.stdout);
  lines(child.stderr);
  child.on('error', (e) => say(`Could not start ${cmd[0]}: ${e.message}. Is it installed? (README.md, "Run it")`));
  child.on('close', (code) => {
    run.code = code;
    say(code === 0 ? '--- Done: every test passed.' : `--- Done: something failed (exit ${code}). The report: ${REPORT}`);
    run.child = null;
    run.label = null;
    for (const listener of run.listeners) listener(null);
  });
  return null;
}

function stop() {
  const child = run.child;
  if (!child) return;
  say('--- Stopping...');
  if (WIN) spawnSync('taskkill', ['/pid', String(child.pid), '/T', '/F']);
  else {
    try {
      process.kill(-child.pid, 'SIGTERM');
    } catch {
      child.kill('SIGTERM');
    }
  }
}

// ---- The page --------------------------------------------------------------------------------

const PAGE = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Test library</title><style>
:root{--bg:#fbfbfa;--fg:#1d1d1f;--dim:#6b6b70;--line:#e3e3e0;--card:#fff;--accent:#2357d9;--ok:#1d7f45;--bad:#c0362c;--skip:#9a7b12}
@media (prefers-color-scheme:dark){:root{--bg:#141416;--fg:#ececee;--dim:#9a9aa2;--line:#2c2c31;--card:#1c1c20;--accent:#7aa2ff;--ok:#5fcf8c;--bad:#ff7b6e;--skip:#e0c25a}}
*{box-sizing:border-box}body{margin:0;font:14px/1.45 system-ui,sans-serif;background:var(--bg);color:var(--fg)}
header{padding:20px 24px 8px}h1{font-size:20px;margin:0}header p{margin:4px 0 0;color:var(--dim)}
main{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:16px;padding:8px 24px 24px}@media (max-width:900px){main{grid-template-columns:1fr}}
section{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:14px 16px}h2{font-size:14px;margin:0 0 8px;text-transform:uppercase;letter-spacing:.04em;color:var(--dim)}
.fam{display:flex;align-items:center;gap:10px;padding:8px 0;border-top:1px solid var(--line)}.fam:first-of-type{border-top:0}.fam b{min-width:90px}.fam span{flex:1;color:var(--dim)}
button{font:inherit;border:1px solid var(--line);background:var(--bg);color:var(--fg);border-radius:6px;padding:4px 10px;cursor:pointer}button.run{border-color:var(--accent);color:var(--accent)}button:disabled{opacity:.4;cursor:default}
.group{margin-top:10px}.group summary{cursor:pointer;font-weight:600;padding:4px 0}.test{display:flex;align-items:center;gap:8px;padding:3px 0 3px 14px}.test span{flex:1;overflow-wrap:anywhere}
.dot{width:9px;height:9px;border-radius:50%;background:var(--line);flex:none}.passed{background:var(--ok)}.failed{background:var(--bad)}.skipped,.pending{background:var(--skip)}
.tag{font-size:11px;color:var(--dim);border:1px solid var(--line);border-radius:9px;padding:0 6px}
#log{height:60vh;overflow:auto;background:var(--bg);border:1px solid var(--line);border-radius:6px;padding:8px;font:12px/1.4 ui-monospace,Menlo,Consolas,monospace;white-space:pre-wrap}
.bar{display:flex;gap:8px;align-items:center;margin-bottom:8px}.bar span{flex:1;color:var(--dim)}input{font:inherit;width:100%;padding:6px 8px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--fg);margin-bottom:6px}
</style></head><body><header><h1 id="h">Test library</h1><p id="sub"></p></header><main>
<div><section><h2>Families</h2><div id="fams"></div></section><section style="margin-top:16px"><h2>Every test</h2><input id="q" placeholder="Find a test"><div id="tests"></div></section></div>
<section><div class="bar"><span id="state">Nothing running.</span><button id="failed">Run the failed again</button><button id="stop" disabled>Stop</button></div><div id="log"></div></section>
</main><script>
const KEY = new URLSearchParams(location.search).get('k');
const api = (path, body) => fetch(path, { method: body ? 'POST' : 'GET', headers: { 'x-key': KEY, 'content-type': 'application/json' }, body: body && JSON.stringify(body) }).then((r) => r.json());
let data = { families: [], tests: [], results: {} };
const el = (tag, attrs = {}, ...kids) => { const e = document.createElement(tag); Object.assign(e, attrs); e.append(...kids); return e; };
function draw() {
  document.getElementById('h').textContent = data.site + ': the test library';
  document.getElementById('sub').textContent = data.framework + ' suite. Click Run: the suite runs it here, on this computer, and shows what happens.';
  const busy = Boolean(data.running);
  const fams = document.getElementById('fams'); fams.replaceChildren();
  for (const f of data.families) {
    const n = data.tests.filter((t) => t.families.includes(f.name)).length;
    fams.append(el('div', { className: 'fam' }, el('b', {}, f.name), el('span', {}, f.what + ' (' + n + ' test' + (n === 1 ? '' : 's') + ')'), el('button', { className: 'run', disabled: busy || !n, onclick: () => go({ family: f.name }, 'the ' + f.name + ' family') }, 'Run')));
  }
  const q = document.getElementById('q').value.toLowerCase();
  const box = document.getElementById('tests'); box.replaceChildren();
  const groups = new Map();
  for (const t of data.tests) if (!q || (t.title + ' ' + t.group + ' ' + t.families.join(' ')).toLowerCase().includes(q)) groups.set(t.group, [...(groups.get(t.group) || []), t]);
  for (const [g, ts] of groups) {
    const d = el('details', { className: 'group', open: Boolean(q) }, el('summary', {}, g + ' (' + ts.length + ') ', el('button', { className: 'run', disabled: busy, onclick: (e) => { e.preventDefault(); go(target(ts), g); } }, 'Run all')));
    for (const t of ts) d.append(el('div', { className: 'test' }, el('i', { className: 'dot ' + (data.results[t.id] || '') , title: data.results[t.id] || 'not run yet' }), el('span', {}, t.title), ...t.families.map((f) => el('em', { className: 'tag' }, f)), el('button', { className: 'run', disabled: busy, onclick: () => go(target([t]), t.title) }, 'Run')));
    box.append(d);
  }
  document.getElementById('stop').disabled = !busy;
  document.getElementById('failed').disabled = busy || !Object.values(data.results).includes('failed');
  document.getElementById('state').textContent = busy ? 'Running ' + data.running + '...' : 'Nothing running.';
}
const target = (ts) => (data.kind === 'java' ? { tests: ts.map((t) => t.id) } : { specs: ts.map((t) => t.file) });
async function go(what, label) { const r = await api('/api/run', { what, label }); if (r.error) alert(r.error); refresh(); }
async function refresh() { data = await api('/api/library'); draw(); }
document.getElementById('q').oninput = draw;
document.getElementById('stop').onclick = () => api('/api/stop', {});
document.getElementById('failed').onclick = () => go(target(data.tests.filter((t) => data.results[t.id] === 'failed')), 'the failed tests');
const log = document.getElementById('log');
const events = new EventSource('/api/events?k=' + KEY);
events.onmessage = (m) => { const line = JSON.parse(m.data); if (line === null) { refresh(); return; } log.append(line + '\\n'); log.scrollTop = log.scrollHeight; };
refresh();
</script></body></html>`;

const server = createServer((req, res) => {
  const url = new URL(req.url ?? '/', 'http://127.0.0.1');
  const key = req.headers['x-key'] ?? url.searchParams.get('k');
  const json = (value) => {
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify(value));
  };
  if (url.pathname === '/' && key === KEY) {
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return res.end(PAGE);
  }
  if (key !== KEY) {
    res.writeHead(403);
    return res.end('Open the test library from its own address (node menu/library.mjs prints it).');
  }
  if (url.pathname === '/api/library') return json(library());
  if (url.pathname === '/api/events') {
    res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-cache' });
    for (const line of run.lines) res.write(`data: ${JSON.stringify(line)}\n\n`);
    const listener = (line) => res.write(`data: ${JSON.stringify(line)}\n\n`);
    run.listeners.add(listener);
    req.on('close', () => run.listeners.delete(listener));
    return;
  }
  if (req.method === 'POST') {
    let body = '';
    req.on('data', (c) => (body += c));
    req.on('end', () => {
      const asked = body ? JSON.parse(body) : {};
      if (url.pathname === '/api/run') return json({ error: start(asked.what ?? {}, String(asked.label ?? 'tests')) });
      if (url.pathname === '/api/stop') {
        stop();
        return json({});
      }
      res.writeHead(404);
      res.end();
    });
    return;
  }
  res.writeHead(404);
  res.end();
});

server.listen(Number(process.env.SUITE_LIBRARY_PORT || 0), '127.0.0.1', () => {
  const address = `http://127.0.0.1:${server.address().port}/?k=${KEY}`;
  console.log(`The test library: ${address}\n(only on this computer; Ctrl+C here closes it)`);
  if (process.env.SUITE_LIBRARY_NO_OPEN) return;
  const viewer = WIN ? ['cmd', '/c', 'start', '', address] : process.platform === 'darwin' ? ['open', address] : ['xdg-open', address];
  spawnSync(viewer[0], viewer.slice(1), { stdio: 'ignore' });
});
process.on('SIGINT', () => {
  stop();
  process.exit(0);
});
